class Solution:
    def numberOfWinningSequences(self, s: str) -> int:
        MOD = 10 ** 9 + 7
        id = {'F': 0, 'W': 1, 'E': 2}
        beat = [[0] * 3 for _ in range(3)]
        beat[1][0] = 1; beat[0][1] = -1
        beat[0][2] = 1; beat[2][0] = -1
        beat[2][1] = 1; beat[1][2] = -1
        n = len(s)
        off = n
        W = 2 * n + 1
        dp = [[0] * W for _ in range(3)]
        for b in range(3):
            dp[b][off + beat[b][id[s[0]]]] = 1
        for i in range(1, n):
            nd = [[0] * W for _ in range(3)]
            a = id[s[i]]
            for last in range(3):
                row = dp[last]
                for b in range(3):
                    if b == last:
                        continue
                    d = beat[b][a]
                    tgt = nd[b]
                    for j in range(W):
                        if row[j]:
                            tgt[j + d] = (tgt[j + d] + row[j]) % MOD
            dp = nd
        return sum(dp[b][j] for b in range(3) for j in range(off)) % MOD

