class Solution {
public:
    int numberOfWinningSequences(string s) {
        const long long MOD = 1e9 + 7;
        auto id = [](char c) { return c == 'F' ? 0 : c == 'W' ? 1 : 2; };
        int beat[3][3] = {0};
        beat[1][0] = 1; beat[0][1] = -1;
        beat[0][2] = 1; beat[2][0] = -1;
        beat[2][1] = 1; beat[1][2] = -1;
        int n = s.size(), off = n, W = 2 * n + 1;
        vector<vector<long long>> dp(3, vector<long long>(W, 0));
        for (int b = 0; b < 3; b++) dp[b][off + beat[b][id(s[0])]] = 1;
        for (int i = 1; i < n; i++) {
            vector<vector<long long>> nd(3, vector<long long>(W, 0));
            int a = id(s[i]);
            for (int last = 0; last < 3; last++)
                for (int b = 0; b < 3; b++) {
                    if (b == last) continue;
                    int d = beat[b][a];
                    for (int j = 0; j < W; j++)
                        if (dp[last][j])
                            nd[b][j + d] = (nd[b][j + d] + dp[last][j]) % MOD;
                }
            dp.swap(nd);
        }
        long long ans = 0;
        for (int b = 0; b < 3; b++)
            for (int j = 0; j < off; j++) ans = (ans + dp[b][j]) % MOD;
        return (int) ans;
    }
};

