class Solution {
    public int numberOfWinningSequences(String s) {
        final long MOD = 1000000007L;
        int n = s.length();
        int[] id = new int[128];
        id['F'] = 0; id['W'] = 1; id['E'] = 2;
        int[][] beat = new int[3][3];
        beat[1][0] = 1; beat[0][1] = -1;
        beat[0][2] = 1; beat[2][0] = -1;
        beat[2][1] = 1; beat[1][2] = -1;
        int off = n, W = 2 * n + 1;
        long[][] dp = new long[3][W];
        for (int b = 0; b < 3; b++) dp[b][off + beat[b][id[s.charAt(0)]]] = 1;
        for (int i = 1; i < n; i++) {
            long[][] nd = new long[3][W];
            int a = id[s.charAt(i)];
            for (int last = 0; last < 3; last++)
                for (int b = 0; b < 3; b++) {
                    if (b == last) continue;
                    int d = beat[b][a];
                    for (int j = 0; j < W; j++)
                        if (dp[last][j] != 0)
                            nd[b][j + d] = (nd[b][j + d] + dp[last][j]) % MOD;
                }
            dp = nd;
        }
        long ans = 0;
        for (int b = 0; b < 3; b++)
            for (int j = 0; j < off; j++) ans = (ans + dp[b][j]) % MOD;
        return (int) ans;
    }
}

