var numberOfWinningSequences = function(s) {
  const MOD = 1e9 + 7;
  const id = { F: 0, W: 1, E: 2 };
  const beat = [[0,0,0],[0,0,0],[0,0,0]];
  beat[1][0] = 1; beat[0][1] = -1;
  beat[0][2] = 1; beat[2][0] = -1;
  beat[2][1] = 1; beat[1][2] = -1;
  const n = s.length, off = n, W = 2 * n + 1;
  let dp = Array.from({length: 3}, () => new Array(W).fill(0));
  for (let b = 0; b < 3; b++) dp[b][off + beat[b][id[s[0]]]] = 1;
  for (let i = 1; i < n; i++) {
    const nd = Array.from({length: 3}, () => new Array(W).fill(0));
    const a = id[s[i]];
    for (let last = 0; last < 3; last++)
      for (let b = 0; b < 3; b++) {
        if (b === last) continue;
        const d = beat[b][a];
        for (let j = 0; j < W; j++)
          if (dp[last][j]) nd[b][j + d] = (nd[b][j + d] + dp[last][j]) % MOD;
      }
    dp = nd;
  }
  let ans = 0;
  for (let b = 0; b < 3; b++)
    for (let j = 0; j < off; j++) ans = (ans + dp[b][j]) % MOD;
  return ans;
};
